insert into products (id, name, description, price_minor, currency, images, category_id, featured, created_at) values
  ('relaxed-linen-shirt', 'Relaxed Linen Shirt', 'A breezy button-down cut from washed European linen. Slightly oversized through the body with a curved hem that works tucked or loose.', 7800, 'USD', '["https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=900&q=80","https://images.unsplash.com/photo-1562157873-818bc0726f68?w=900&q=80"]'::jsonb, 'women', true, '2026-06-28T10:00:00.000Z'),
  ('ribbed-cotton-tee', 'Ribbed Cotton Tee', 'A close-fitting ribbed tee in soft organic cotton. The kind of layer you end up owning in three colors.', 3200, 'USD', '["https://images.unsplash.com/photo-1576566588028-4147f3842f27?w=900&q=80","https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=900&q=80"]'::jsonb, 'women', false, '2026-07-05T10:00:00.000Z'),
  ('high-rise-straight-jeans', 'High-Rise Straight Jeans', 'Rigid denim with a high rise and a clean straight leg that breaks just above the ankle. Fades beautifully with wear.', 9800, 'USD', '["https://images.unsplash.com/photo-1542272604-787c3835535d?w=900&q=80","https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=900&q=80"]'::jsonb, 'women', false, '2026-05-14T10:00:00.000Z'),
  ('pleated-satin-skirt', 'Pleated Satin Skirt', 'A fluid midi skirt in knife-pleated satin that moves with every step. Sits at the natural waist with a hidden zip.', 11200, 'USD', '["https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?w=900&q=80","https://images.unsplash.com/photo-1529139574466-a303027c1d8b?w=900&q=80"]'::jsonb, 'women', false, '2026-04-19T10:00:00.000Z'),
  ('garment-dyed-tee', 'Garment-Dyed Tee', 'A heavyweight cotton tee, garment dyed for a lived-in tone that only gets better with washing.', 3600, 'USD', '["https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=900&q=80","https://images.unsplash.com/photo-1618354691373-d851c5c3a990?w=900&q=80"]'::jsonb, 'men', false, '2026-06-11T10:00:00.000Z'),
  ('oxford-button-down', 'Oxford Button-Down', 'The classic oxford, done properly. Dense basketweave cotton, a soft unlined collar, and mother-of-pearl buttons.', 8800, 'USD', '["https://images.unsplash.com/photo-1598033129183-c4f50c736f10?w=900&q=80","https://images.unsplash.com/photo-1620012253295-c15cc3e65df4?w=900&q=80"]'::jsonb, 'men', false, '2026-03-22T10:00:00.000Z'),
  ('merino-crewneck', 'Merino Crewneck Sweater', 'Fine-gauge extrafine merino knitted in a classic crewneck. Light enough for offices, warm enough for evenings.', 12800, 'USD', '["https://images.unsplash.com/photo-1520975954732-35dd22299614?w=900&q=80","https://images.unsplash.com/photo-1610384104075-e05c8cf200c3?w=900&q=80"]'::jsonb, 'men', true, '2026-02-08T10:00:00.000Z'),
  ('pleated-chino-trousers', 'Pleated Chino Trousers', 'Single-pleat chinos with a tapered leg and a touch of stretch. Smart with loafers, easy with sneakers.', 7200, 'USD', '["https://images.unsplash.com/photo-1473966968600-fa801b869a1a?w=900&q=80","https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?w=900&q=80"]'::jsonb, 'men', false, '2026-05-30T10:00:00.000Z'),
  ('wrap-midi-dress', 'Wrap Midi Dress', 'A true wrap dress in crinkled viscose with a flattering V-neck and a skirt that falls to mid-calf.', 12400, 'USD', '["https://images.unsplash.com/photo-1595777457583-95e059d581b8?w=900&q=80","https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=900&q=80"]'::jsonb, 'dresses', true, '2026-06-20T10:00:00.000Z'),
  ('linen-sundress', 'Linen Sundress', 'An easy A-line sundress in midweight linen with adjustable straps and deep side pockets.', 9200, 'USD', '["https://images.unsplash.com/photo-1502716119720-b23a93e5fe1b?w=900&q=80","https://images.unsplash.com/photo-1509631179647-0177331693ae?w=900&q=80"]'::jsonb, 'dresses', false, '2026-07-08T10:00:00.000Z'),
  ('pleated-evening-dress', 'Pleated Evening Dress', 'Fine sunray pleats from shoulder to hem in a floor-skimming silhouette. Quietly dramatic.', 16800, 'USD', '["https://images.unsplash.com/photo-1566174053879-31528523f8ae?w=900&q=80","https://images.unsplash.com/photo-1487222477894-8943e31ef7b2?w=900&q=80"]'::jsonb, 'dresses', false, '2026-01-25T10:00:00.000Z'),
  ('knit-sweater-dress', 'Knit Sweater Dress', 'A ribbed knit dress that skims rather than clings, with a mock neck and side slits for ease.', 10800, 'USD', '["https://images.unsplash.com/photo-1434389677669-e08b4cac3105?w=900&q=80","https://images.unsplash.com/photo-1495385794356-15371f348c31?w=900&q=80"]'::jsonb, 'dresses', false, '2026-02-27T10:00:00.000Z'),
  ('belted-trench-coat', 'Belted Trench Coat', 'A double-breasted trench in bonded cotton twill with storm flaps and a waist belt. The forever coat.', 19800, 'USD', '["https://images.unsplash.com/photo-1544022613-e87ca75a784a?w=900&q=80","https://images.unsplash.com/photo-1520975916090-3105956dac38?w=900&q=80"]'::jsonb, 'outerwear', true, '2026-03-08T10:00:00.000Z'),
  ('cropped-denim-jacket', 'Cropped Denim Jacket', 'A boxy, cropped trucker jacket in rigid denim. Cut to sit right at the waistband of high-rise jeans.', 9800, 'USD', '["https://images.unsplash.com/photo-1527016021513-b09758b777bd?w=900&q=80","https://images.unsplash.com/photo-1543076447-215ad9ba6923?w=900&q=80"]'::jsonb, 'outerwear', false, '2026-06-02T10:00:00.000Z'),
  ('leather-biker-jacket', 'Leather Biker Jacket', 'Vegetable-tanned lambskin with an asymmetric zip and just enough hardware. Breaks in like a favorite record.', 24800, 'USD', '["https://images.unsplash.com/photo-1551028719-00167b16eac5?w=900&q=80","https://images.unsplash.com/photo-1520975661595-6453be3f7070?w=900&q=80"]'::jsonb, 'outerwear', false, '2026-04-05T10:00:00.000Z'),
  ('wool-overcoat', 'Wool Overcoat', 'A single-breasted overcoat in brushed Italian wool, cut long with a clean shoulder. Tailoring without the fuss.', 22800, 'USD', '["https://images.unsplash.com/photo-1539533018447-63fcce2678e3?w=900&q=80","https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=900&q=80"]'::jsonb, 'outerwear', true, '2026-01-12T10:00:00.000Z'),
  ('minimal-leather-sneakers', 'Minimal Leather Sneakers', 'Clean court sneakers in full-grain leather on a cupsole, with zero visible branding.', 12800, 'USD', '["https://images.unsplash.com/photo-1549298916-b41d501d3772?w=900&q=80","https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?w=900&q=80"]'::jsonb, 'shoes', true, '2026-05-21T10:00:00.000Z'),
  ('suede-chelsea-boots', 'Suede Chelsea Boots', 'Almond-toe Chelsea boots in water-resistant suede with elastic gussets and a stacked heel.', 16800, 'USD', '["https://images.unsplash.com/photo-1543163521-1bf539c55dd2?w=900&q=80","https://images.unsplash.com/photo-1560769629-975ec94e6a86?w=900&q=80"]'::jsonb, 'shoes', false, '2026-02-14T10:00:00.000Z'),
  ('canvas-high-tops', 'Canvas High-Tops', 'High-top sneakers in heavy duck canvas with a vulcanized sole. A blank slate for everything you wear.', 6800, 'USD', '["https://images.unsplash.com/photo-1525966222134-fcfa99b8ae77?w=900&q=80","https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?w=900&q=80"]'::jsonb, 'shoes', false, '2026-06-25T10:00:00.000Z'),
  ('strappy-heeled-sandals', 'Strappy Heeled Sandals', 'Barely-there sandals with slim leather straps and a sculpted 70mm heel you can actually walk in.', 9800, 'USD', '["https://images.unsplash.com/photo-1596703263926-eb0762ee17e4?w=900&q=80","https://images.unsplash.com/photo-1518049362265-d5b2a6467637?w=900&q=80"]'::jsonb, 'shoes', false, '2026-07-12T10:00:00.000Z'),
  ('structured-leather-tote', 'Structured Leather Tote', 'A clean-lined tote in pebbled leather that holds a 13-inch laptop flat. Unlined, rivet-reinforced, built to age well.', 14800, 'USD', '["https://images.unsplash.com/photo-1548036328-c9fa89d128fa?w=900&q=80","https://images.unsplash.com/photo-1584917865442-de89df76afd3?w=900&q=80"]'::jsonb, 'accessories', true, '2026-04-28T10:00:00.000Z'),
  ('minimalist-watch', 'Minimalist Watch', 'A 36mm brushed steel case, domed sapphire glass, and an Italian leather strap. Tells the time, nothing else.', 15800, 'USD', '["https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=900&q=80","https://images.unsplash.com/photo-1523170335258-f5ed11844a49?w=900&q=80"]'::jsonb, 'accessories', false, '2026-03-15T10:00:00.000Z'),
  ('acetate-sunglasses', 'Acetate Sunglasses', 'Hand-polished acetate frames with UV400 lenses, somewhere between round and square. Unisex fit.', 7800, 'USD', '["https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=900&q=80","https://images.unsplash.com/photo-1572635196237-14b3f281503f?w=900&q=80"]'::jsonb, 'accessories', false, '2026-05-07T10:00:00.000Z'),
  ('canvas-weekender', 'Canvas Weekender Bag', 'A carry-on-sized duffle in waxed canvas with leather handles and a detachable shoulder strap.', 11800, 'USD', '["https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=900&q=80","https://images.unsplash.com/photo-1547949003-9792a18a2601?w=900&q=80"]'::jsonb, 'accessories', false, '2026-01-30T10:00:00.000Z');
